package ai.eva.android.probe;
import org.json.*;import java.io.*;import java.net.URI;import android.content.Intent;
/** Management only; credentials stay in native config, never returned to WebView. */
final class McpSettings {
 static JSONObject tomlObject(JSONObject value)throws Exception{JSONObject clean=new JSONObject();java.util.Iterator<String> keys=value.keys();while(keys.hasNext()){String key=keys.next();Object v=value.get(key);if(v==JSONObject.NULL)continue;if(v instanceof JSONObject)v=tomlObject((JSONObject)v);else if(v instanceof JSONArray){JSONArray a=new JSONArray();for(int n=0;n<((JSONArray)v).length();n++){Object item=((JSONArray)v).get(n);if(item==JSONObject.NULL)continue;a.put(item instanceof JSONObject?tomlObject((JSONObject)item):item);}v=a;}clean.put(key,v);}return clean;}
 static void validateToken(String token)throws IOException{if(token.length()>8192||token.contains("\r")||token.contains("\n"))throw new IOException("无效凭据");}
 static void rememberSecrets(KernelHost host,JSONObject servers){java.util.Iterator<String> names=servers.keys();while(names.hasNext()){JSONObject server=servers.optJSONObject(names.next());if(server==null)continue;for(String field:new String[]{"http_headers","env"}){JSONObject values=server.optJSONObject(field);if(values==null)continue;java.util.Iterator<String> keys=values.keys();while(keys.hasNext()){String key=keys.next();if(!key.toLowerCase(java.util.Locale.ROOT).matches(".*(auth|token|secret|password|credential|cookie|key).*"))continue;String value=values.optString(key);if(value.isEmpty())continue;synchronized(host.secrets){if(!host.secrets.contains(value))host.secrets.add(value);if(value.startsWith("Bearer ")&&!host.secrets.contains(value.substring(7)))host.secrets.add(value.substring(7));}}}}}
 static synchronized void credential(KernelHost host,String name,String token)throws Exception{validateName(name);validateToken(token);JSONObject read=host.rpc("config/read",new JSONObject().put("includeLayers",false));JSONObject servers=read.getJSONObject("config").optJSONObject("mcp_servers"),server=servers==null?null:servers.optJSONObject(name);if(server==null||!server.has("url"))throw new IOException("HTTP 连接不存在");rememberSecrets(host,servers);JSONObject headers=server.optJSONObject("http_headers");if(headers==null)headers=new JSONObject();java.util.ArrayList<String> remove=new java.util.ArrayList<>();java.util.Iterator<String> keys=headers.keys();while(keys.hasNext()){String key=keys.next();if(key.equalsIgnoreCase("Authorization"))remove.add(key);}for(String key:remove)headers.remove(key);if(!token.isEmpty())headers.put("Authorization","Bearer "+token);server.put("http_headers",headers);server.remove("bearer_token_env_var");JSONObject envHeaders=server.optJSONObject("env_http_headers");if(envHeaders!=null){remove.clear();keys=envHeaders.keys();while(keys.hasNext()){String key=keys.next();if(key.equalsIgnoreCase("Authorization"))remove.add(key);}for(String key:remove)envHeaders.remove(key);}rememberSecrets(host,servers);host.rpc("config/value/write",new JSONObject().put("keyPath","mcp_servers").put("value",tomlObject(servers)).put("mergeStrategy","replace"));host.reloadMcpConnections();}
 static void validateName(String name)throws IOException{if(!name.matches("[A-Za-z0-9_-]{1,80}"))throw new IOException("名称仅支持字母、数字、下划线和连字符");}
 static void validateUrl(String url)throws Exception{URI uri=new URI(url);if(!"https".equals(uri.getScheme())||uri.getHost()==null||uri.getUserInfo()!=null||uri.getQuery()!=null||uri.getFragment()!=null)throw new IOException("请输入无凭据、无查询参数的 HTTPS MCP 地址");}
 static synchronized JSONObject call(KernelHost host,JSONObject args)throws Exception{
  String action=args.optString("action","list"),name=args.optString("name");
  JSONObject read=host.rpc("config/read",new JSONObject().put("includeLayers",false));JSONObject config=read.getJSONObject("config"),servers=config.optJSONObject("mcp_servers");if(servers==null)servers=new JSONObject();
  rememberSecrets(host,servers);
  if(action.equals("list")){JSONArray rows=new JSONArray();java.util.Iterator<String> keys=servers.keys();while(keys.hasNext()){String key=keys.next();JSONObject server=servers.optJSONObject(key);if(server!=null)rows.put(new JSONObject().put("name",key).put("enabled",server.optBoolean("enabled",true)).put("transport",server.has("url")?"http":"stdio").put("hasCredential",server.has("bearer_token_env_var")||server.optJSONObject("http_headers")!=null&&server.optJSONObject("http_headers").length()>0));}return new JSONObject().put("servers",rows);}
  validateName(name);
  if(action.equals("credential")){JSONObject server=servers.optJSONObject(name);if(server==null||!server.has("url"))throw new IOException("仅 HTTP 连接支持静态凭据");host.context.startActivity(new Intent(host.context,McpCredentialActivity.class).putExtra("name",name).putExtra("api",host.apiOnly).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));return new JSONObject().put("credentialOpened",true);}
  if(action.equals("resources"))return host.rpc("mcpServerStatus/list",new JSONObject().put("serverName",name).put("detail","full").put("limit",100));
  if(action.equals("resourceRead")){String uri=args.getString("uri");if(uri.length()>8192)throw new IOException("资源地址过长");JSONObject value=host.rpc("mcpServer/resource/read",new JSONObject().put("server",name).put("uri",uri));JSONArray contents=value.optJSONArray("contents"),output=new JSONArray();if(contents!=null)for(int n=0;n<contents.length()&&n<20;n++){JSONObject content=contents.optJSONObject(n);if(content==null)continue;String text=content.optString("text");output.put(new JSONObject().put("uri",content.optString("uri")).put("mimeType",content.optString("mimeType")).put("text",text.length()>65536?text.substring(0,65536):text).put("truncated",text.length()>65536).put("binary",content.has("blob")));}return new JSONObject().put("contents",output);}
  if(action.equals("status"))return host.rpc("mcpServerStatus/list",new JSONObject().put("serverName",name).put("detail","toolsAndAuthOnly").put("limit",100));
  if(action.equals("login")){JSONObject result=host.rpc("mcpServer/oauth/login",new JSONObject().put("name",name).put("timeoutSecs",180));String url=result.getString("authorizationUrl");URI uri=new URI(url);if(!"https".equals(uri.getScheme()))throw new IOException("授权地址必须为 HTTPS");host.context.startActivity(new Intent(host.context,ShellActivity.class).putExtra("page","browser").putExtra("initialUrl",url).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));return new JSONObject().put("opened",true);}
  JSONObject server=servers.optJSONObject(name);
  if(action.equals("remove")){if(server==null)throw new IOException("服务器不存在");servers.remove(name);}
  else if(action.equals("toggle")){if(server==null)throw new IOException("服务器不存在");server.put("enabled",args.getBoolean("enabled"));}
  else if(action.equals("save")){
   if(server!=null&&!args.optBoolean("replace"))throw new IOException("同名服务器已存在，请选择替换");
   server=new JSONObject().put("enabled",true);String kind=args.optString("transport");
   if(kind.equals("http")){String url=args.getString("url");validateUrl(url);server.put("url",url);}
   else if(kind.equals("stdio")){String command=args.getString("command").trim();if(command.isEmpty()||command.length()>1024||command.contains("\n"))throw new IOException("无效命令");JSONArray values=args.optJSONArray("args");if(values==null)values=new JSONArray();if(values.length()>64)throw new IOException("参数过多");for(int i=0;i<values.length();i++)if(!(values.get(i) instanceof String))throw new IOException("参数须为字符串数组");server.put("command",command).put("args",values);}
   else throw new IOException("未知连接方式");servers.put(name,server);
  }else if(!action.equals("reload"))throw new IOException("未知 MCP 操作");
  if(!action.equals("reload"))host.rpc("config/value/write",new JSONObject().put("keyPath","mcp_servers").put("value",tomlObject(servers)).put("mergeStrategy","replace"));
  host.reloadMcpConnections();return new JSONObject().put("saved",true).put("instruction","已保存并请求重载；请测试连接。已有会话可能需要重新打开。");
 }
}
